cat > /tmp/fix_tui.py << 'EOF'
import re

with open('/app/tui/tui.go', 'r') as f:
    content = f.read()

# Find the block:
# if conts, found := vinfo.CveContents[models.Trivy]; found {
#     for _, cont := range conts {
#         for _, ref := range cont.References {
#             refsMap[ref.Link] = ref
#         }
#     }
# }
pattern = r'if conts, found := vinfo\.CveContents\[models\.Trivy\]; found \{.*?\}'
match = re.search(pattern, content, re.DOTALL)
if not match:
    print("Pattern not found in tui.go")
else:
    start = match.start()
    end = match.end()
    new_block = '''for _, ctype := range models.GetCveContentTypes("trivy") {
        if conts, found := vinfo.CveContents[ctype]; found {
            for _, cont := range conts {
                for _, ref := range cont.References {
                    refsMap[ref.Link] = ref
                }
            }
        }
    }'''
    content = content[:start] + new_block + content[end:]

with open('/app/tui/tui.go', 'w') as f:
    f.write(content)

print("Done editing tui.go")
EOF
python3 /tmp/fix_tui.py

